    explanation: '眼の壁雲置換サイクル（ERC）は発達した台風でみられる現象で、外側に形成された新たな眼壁（アウターアイウォール）が内側の眼壁を弱めながら置き換わる。この過程で最大風速は一時的に弱まるが暴風域は拡大する傾向があり、台風強度予測の不確実性を高める要因として重要視される。\n【図解】\n★ポイント: ERC＝内側眼壁が外側の新しい眼壁（アウターアイウォール）に置き換わる過程\n○正: Dの通り、置換の過程で最大風速は一時弱まるが暴風域（眼の規模）はむしろ拡大する\n×誤: Bのように弱い熱帯低気圧でのみ発生するとする記述、Cのように中心気圧が変化しないとする記述、Aのように予測不確実性に影響しないとする記述はいずれも誤り\n⚠注意: ERCは強度予測を難しくする代表的要因であり、実技試験でも台風の急変現象として重要な着眼点となる\n→ 結論: ERCの構造変化と影響を正確に述べたDが正解（D）',
